const rows = $input.all().map(i => i.json);
const fixedCols = ['Variant', 'Product Name', 'SKU'];
const firstRow = rows[0] || {};
const allCols = Object.keys(firstRow);
const dateCols = allCols.filter(c => !fixedCols.includes(c) && !c.startsWith('_'));

return rows.filter(r => r['Product Name']).map(r => {
  let latestCol = null;
  let rawValue = null;
  for (let i = dateCols.length - 1; i >= 0; i--) {
    const col = dateCols[i];
    const val = r[col];
    if (val !== null && val !== undefined && val !== '') {
      latestCol = col;
      rawValue = val;
      break;
    }
  }

  let currentStock = 0;
  let inProduction = 0;

  if (typeof rawValue === 'number') {
    currentStock = Math.floor(rawValue);
  } else if (typeof rawValue === 'string') {
    const stockMatch = rawValue.match(/^(\d+)/);
    const prodMatch = rawValue.match(/\((\d+)\s*pcs?\s*in\s*production\)/i);
    if (stockMatch) currentStock = parseInt(stockMatch[1]);
    if (prodMatch) inProduction = parseInt(prodMatch[1]);
  }

  return {
    json: {
      product_name_sheet: r['Product Name'],
      sku: String(r['SKU'] || '').replace(/\.0$/, ''),
      current_stock: currentStock,
      in_production: inProduction,
      effective_stock: currentStock + inProduction,
      latest_col: latestCol
    }
  };
});

const dtRows = $input.all().map(i => i.json);
const sheetRows = $('Parse Sheet').all().map(i => i.json);

if (dtRows.length === 0) {
  return [{ json: { redAlerts: [], orangeAlerts: [], total: 0, error: 'DataTable is empty, run the thresholds workflow first', checkedAt: new Date().toISOString() } }];
}

const dtBySku = {};
for (const r of dtRows) dtBySku[String(r.sku)] = r;

const redAlerts = [];
const orangeAlerts = [];
let latestColRef = null;

for (const s of sheetRows) {
  const dt = dtBySku[s.sku];
  if (!dt) continue;
  if (dt.mode === 'excluded') continue;
  if (dt.red_threshold == null || dt.orange_threshold == null) continue;
  const red = Number(dt.red_threshold || 0);
  const orange = Number(dt.orange_threshold || 0);
  if (red === 0 && orange === 0) continue;
  const compareStock = s.effective_stock;
  const merged = { ...s, ...dt, compare_stock: compareStock };
  if (s.latest_col) latestColRef = s.latest_col;
  if (compareStock <= red) redAlerts.push(merged);
  else if (compareStock <= orange) orangeAlerts.push(merged);
}

return [{ json: { redAlerts, orangeAlerts, total: redAlerts.length + orangeAlerts.length, latestCol: latestColRef, checkedAt: new Date().toISOString() } }];

const esc = s => String(s == null ? '' : s).replace(/([_*\[`])/g, '\\$1'); // escape legacy Markdown specials in product names
const d = $input.first().json;
const red = d.redAlerts || [];
const orange = d.orangeAlerts || [];
const today = new Date().toLocaleDateString('en-US');

let text = `🚨 *Low stock alert*, ${today}\n\n`;

if (red.length > 0) {
  text += `🔴 *CRITICAL (${red.length})*\n━━━━━━━━━━━━━━━━━━\n`;
  for (const p of red) {
    const prod = p.in_production > 0 ? ` (+${p.in_production} in production)` : '';
    const avg = Number(p.avg_daily_sales_30d || 0).toFixed(1);
    text += `• *${esc(p.product_name_sheet)}*\n`;
    text += `  Stock: ${p.current_stock} units${prod}\n`;
    text += `  Red threshold: ${p.red_threshold} | Sales/day: ${avg}\n`;
    text += `  ⏰ Order urgently, lead time ${p.lead_time_days} days\n\n`;
  }
}

if (orange.length > 0) {
  text += `🟠 *WATCH (${orange.length})*\n━━━━━━━━━━━━━━━━━━\n`;
  for (const p of orange) {
    const prod = p.in_production > 0 ? ` (+${p.in_production} in production)` : '';
    const avg = Number(p.avg_daily_sales_30d || 0).toFixed(1);
    const avgDaily = Number(p.avg_daily_sales_30d || 0);
    const daysToRed = avgDaily > 0 ? Math.max(0, Math.floor((p.effective_stock - p.red_threshold) / avgDaily)) : 999;
    text += `• *${esc(p.product_name_sheet)}*\n`;
    text += `  Stock: ${p.current_stock} units${prod}\n`;
    text += `  Orange threshold: ${p.orange_threshold} | Sales/day: ${avg}\n`;
    text += `  📦 In ~${daysToRed} days in the red zone\n\n`;
  }
}

text += `━━━━━━━━━━━━━━━━━━\n`;
if (d.latestCol) text += `📊 Data as of "${d.latestCol}"\n`;
text += `🔄 Next check tomorrow 9am`;

if (text.length > 4000) text = text.substring(0, 3990) + '\n…(truncated)';

return [{ json: { text } }];
